  "landing.faq.badge": "FAQ",
  "landing.faq.title": "Frequently Asked",
  "landing.faq.highlight": "Questions",
  "landing.faq.q1": "Can I manage property and service businesses remotely with Easy-Locs?",
  "landing.faq.a1": "Yes. Easy-Locs allows entrepreneurs to create and manage rental properties, accept direct bookings, and run service businesses in multiple cities worldwide — all remotely from a single platform.",
  "landing.faq.q2": "What types of businesses can I run on Easy-Locs?",
  "landing.faq.a2": "You can manage long-term rental properties, accept direct short-term bookings, and run service businesses like cleaning, car rental, concierge, activities, and maintenance across multiple cities.",
  "landing.faq.q3": "How many countries does Easy-Locs support?",
  "landing.faq.a3": "Easy-Locs supports operations in over 110 countries with localized compliance, 120+ currencies, and documents available in 31 languages.",
  "landing.faq.q4": "Is Easy-Locs free to start?",
  "landing.faq.a4": "Yes, Easy-Locs offers a free trial. Plans start at €9.99/month with unlimited properties, tenants, and services included.",
  "landing.faq.q5": "How do payments work on the platform?",
  "landing.faq.a5": "Easy-Locs supports credit cards, SEPA direct debit, bank transfers, and custom payment links. All payments go directly to your account.",
  "landing.faq.q6": "Can I generate legal documents like leases and receipts?",
  "landing.faq.a6": "Yes. Easy-Locs generates country-specific legal documents including leases, rent receipts, inventory reports, and formal notices — all compliant with local regulations.",

